const BlogPage = ({ content = defaultBlogContent }) => {
  const [blogSearch, setBlogSearch] = useState("");
  const [blogCategory, setBlogCategory] = useState("Tümü");

  const authors = useMemo(
    () =>
      (Array.isArray(content?.authors) ? content.authors : [])
        .filter((author) => author?.slug && author?.name),
    [content]
  );

  const publishedPosts = useMemo(
    () =>
      [...(Array.isArray(content?.posts) ? content.posts : [])]
        .filter((post) => String(post?.status || "").toLowerCase() !== "draft")
        .sort((a, b) => {
          const orderDiff =
            Number(b?.sortOrder ?? 0) - Number(a?.sortOrder ?? 0);
          if (orderDiff !== 0) return orderDiff;

          const aTime = Number(
            String(a?.id || "").match(/blog-(\d+)/)?.[1] || 0
          );
          const bTime = Number(
            String(b?.id || "").match(/blog-(\d+)/)?.[1] || 0
          );
          return bTime - aTime;
        }),
    [content]
  );

  const categories = useMemo(() => {
    const sourceCategories =
      Array.isArray(content?.categories) && content.categories.length
        ? content.categories
        : blogCategories;

    const normalized = sourceCategories
      .map((item) =>
        typeof item === "string"
          ? item
          : String(item?.name || item?.label || item?.title || "").trim()
      )
      .filter(Boolean);

    const postCategories = publishedPosts
      .map((post) => String(post?.category || "").trim())
      .filter(Boolean);

    return [
      "Tümü",
      ...Array.from(
        new Set(
          [...normalized, ...postCategories].filter(
            (item) =>
              String(item).toLocaleLowerCase("tr-TR") !==
              "tümü".toLocaleLowerCase("tr-TR")
          )
        )
      ),
    ];
  }, [content, publishedPosts]);

  const filteredPosts = useMemo(() => {
    const q = blogSearch.trim().toLocaleLowerCase("tr-TR");

    return publishedPosts.filter((post) => {
      const categoryOk =
        blogCategory === "Tümü" ||
        String(post?.category || "")
          .toLocaleLowerCase("tr-TR")
          .includes(blogCategory.toLocaleLowerCase("tr-TR"));

      if (!categoryOk) return false;
      if (!q) return true;

      const author = authors.find(
        (item) =>
          String(item?.slug || "") === String(post?.authorSlug || "")
      );

      const haystack = [
        post?.title,
        post?.excerpt,
        post?.category,
        post?.authorName,
        author?.name,
      ]
        .filter(Boolean)
        .join(" ")
        .toLocaleLowerCase("tr-TR");

      return haystack.includes(q);
    });
  }, [publishedPosts, blogCategory, blogSearch, authors]);

  const openPost = (post) => {
    if (!post?.slug) return;
    window.location.hash = `#/blog/${post.slug}`;
  };

  const openAuthor = (author) => {
    if (!author?.slug) return;
    window.location.hash = `#/yazarlar/${author.slug}`;
  };

  const openAuthors = () => {
    window.location.hash = "#/yazarlar";
  };

  const backHome = () => {
    window.location.hash = "#/";
  };

  return (
    <main className="blog4">
      <section
        className="blog4Hero"
        style={{
          "--blog4-cover": `url("${content?.heroImage || defaultBlogContent.heroImage}")`,
        }}
      >
        <div className="blog4Hero__veil" />
        <div className="blog4Hero__grain" />

        <header className="blog4Topbar">
          <button type="button" className="blog4Back" onClick={backHome}>
            ← ANA SAYFA
          </button>
          <div className="blog4Journal">KAAN ÖZKAN / EDITORIAL JOURNAL</div>
          <div className="blog4Roman">MMXXVI</div>
        </header>

        <div className="blog4Hero__content">
          <div className="blog4Hero__eyebrow">DÜŞÜNCE · İNSAN · İLİŞKİ</div>

          <h1 className="blog4Hero__title">
            <span>Blog</span>
            <em>&amp;</em>
            <span className="blog4Hero__outline">İçerikler</span>
          </h1>

          <p className="blog4Hero__copy">
            Psikoloji, ilişkiler, aile yaşamı ve sosyal hizmet üzerine;
            sade, güçlü ve düşünmeye alan açan editoryal içerikler.
          </p>

          <div className="blog4Hero__actions">
            <button
              type="button"
              className="blog4Primary"
              onClick={() =>
                document
                  .getElementById("blog4-all-posts")
                  ?.scrollIntoView({ behavior: "smooth" })
              }
            >
              Tüm Yazıları Keşfet <span>↓</span>
            </button>

            <button type="button" className="blog4Ghost" onClick={openAuthors}>
              Yazarları Tanı <span>↗</span>
            </button>
          </div>

          <div className="blog4Hero__quote">
            “İyi bir yaşam, doğru bilgiyle başlar.”
          </div>

          <div className="blog4Hero__visualStage" aria-hidden="true">
            <div className="blog4Hero__visualFrame">
              <img
                src={content?.heroImage || defaultBlogContent.heroImage}
                alt=""
                decoding="async"
              />
              <span className="blog4Hero__visualGlow"/>
              <div className="blog4Hero__visualStamp">
                <small>KAAN ÖZKAN</small>
                <strong>JOURNAL</strong>
                <i>2026</i>
              </div>
            </div>
            <div className="blog4Hero__visualLine"/>
          </div>
        </div>
      </section>

      <section className="blog4Content" id="blog4-all-posts">
        <div className="blog4Content__ambient blog4Content__ambient--one" />
        <div className="blog4Content__ambient blog4Content__ambient--two" />

        <div className="blog4Toolbar">
          <label className="blog4Search">
            <span>⌕</span>
            <input
              value={blogSearch}
              onChange={(e) => setBlogSearch(e.target.value)}
              placeholder="Yazı ara..."
            />
          </label>

          <div className="blog4Categories">
            {categories.map((category) => (
              <button
                type="button"
                key={category}
                className={blogCategory === category ? "is-active" : ""}
                onClick={() => setBlogCategory(category)}
              >
                {category}
              </button>
            ))}
          </div>
        </div>

        <div className="blog4SectionHead">
          <div>
            <span className="blog4SectionHead__kicker">EDİTORYAL SEÇKİ</span>
            <h2>Yeni Yazılar</h2>
          </div>
          <p>
            En yeni içeriklerden arşivdeki tüm yazılara kadar her şey burada.
          </p>
        </div>

        {filteredPosts.length ? (
          <div className="blog4Grid">
            {filteredPosts.map((post, index) => {
              const author = authors.find(
                (item) =>
                  String(item?.slug || "") ===
                  String(post?.authorSlug || "")
              );

              const image =
                post?.image ||
                post?.cover ||
                post?.coverImage ||
                content?.heroImage ||
                defaultBlogContent.heroImage;

              return (
                <article
                  key={post?.slug || post?.id || `${post?.title}-${index}`}
                  className={`blog4Card ${
                    index % 7 === 0 ? "blog4Card--wide" : ""
                  }`}
                >
                  <button
                    type="button"
                    className="blog4Card__media"
                    onClick={() => openPost(post)}
                    aria-label={post?.title || "Yazıyı aç"}
                  >
                    {image ? (
                      <img
                        src={image}
                        alt=""
                        loading="lazy"
                        decoding="async"
                      />
                    ) : (
                      <div className="blog4Card__placeholder" />
                    )}
                    <span className="blog4Card__shade" />
                    {post?.category && (
                      <span className="blog4Card__category">
                        {post.category}
                      </span>
                    )}
                  </button>

                  <div className="blog4Card__body">
                    <button
                      type="button"
                      className="blog4Card__title"
                      onClick={() => openPost(post)}
                    >
                      {post?.title}
                    </button>

                    {post?.excerpt && (
                      <p className="blog4Card__excerpt">{post.excerpt}</p>
                    )}

                    <div className="blog4Card__meta">
                      <div>
                        {post?.date && <span>{post.date}</span>}
                        {post?.readTime && <span>{post.readTime}</span>}
                      </div>

                      {author ? (
                        <button
                          type="button"
                          className="blog4Card__author blog4Card__authorWithAvatar"
                          onClick={() => openAuthor(author)}
                        >
                          <span className="blog4Card__authorAvatar">
                            {author?.image || author?.photo ? (
                              <img src={author.image || author.photo} alt="" loading="lazy" decoding="async" />
                            ) : (
                              <span>{String(author?.name || "?").charAt(0)}</span>
                            )}
                          </span>
                          <span>{author.name}</span>
                        </button>
                      ) : post?.authorName ? (
                        <span className="blog4Card__authorText">
                          {post.authorName}
                        </span>
                      ) : null}
                    </div>

                    <button
                      type="button"
                      className="blog4Card__read"
                      onClick={() => openPost(post)}
                    >
                      Yazıyı Oku <span>↗</span>
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        ) : (
          <div className="blog4Empty">
            Bu aramayla eşleşen bir yazı bulunamadı.
          </div>
        )}


        <div className="blog4FooterLine">
          <span />
          <em>Bilgi, daha güçlü bir sen için.</em>
          <span />
        </div>
      </section>
    </main>
  );
};

function AuthorsPage({ content = defaultBlogContent }) {
  const authors = (Array.isArray(content.authors) ? content.authors : [])
    .filter((author)=>author?.slug && author?.name);

  const posts = (Array.isArray(content.posts) ? content.posts : [])
    .filter((post)=>post.status !== "draft");

  const countFor = (author) =>
    posts.filter((post)=>String(post.authorSlug||"")===String(author.slug||"")).length;

  return (
    <main className="authorsV3">
      <section className="authorsV3Hero">
        <a href="#/blog" className="authorsV3Hero__back">← BLOG'A DÖN</a>
        <span className="authorsV3Hero__ghost" aria-hidden="true">VOICES</span>
        <div>
          <span>THE CONTRIBUTORS / 2026</span>
          <h1>Yazarlar <em>Odası</em></h1>
          <p>
            Bilgi, deneyim ve farklı disiplinlerin ortak bir editoryal alanda
            buluştuğu; her profilin kendi karakterini taşıdığı yazar seçkisi.
          </p>
        </div>
      </section>

      <section className="authorsV3Grid">
        {authors.length ? authors.map((author,index)=>(
          <a href={`#/yazarlar/${author.slug}`} className="authorsV3Card" key={author.slug}>
            <div className="authorsV3Card__photo">
              {author.image
                ? <img src={author.image} alt={author.name}/>
                : <span>{author.name?.charAt(0)}</span>}
              <small>0{index+1}</small>
              <i/>
            </div>

            <div className="authorsV3Card__body">
              <span>CONTRIBUTOR</span>
              <h2>{author.name}</h2>
              <p className="authorsV3Card__role">{author.role}</p>
              <p>{author.shortBio}</p>
              <div className="authorsV3Card__foot">
                <span><b>{String(countFor(author)).padStart(2,"0")}</b> YAYIN</span>
                <strong>PROFİLİ İNCELE ↗</strong>
              </div>
            </div>
          </a>
        )) : (
          <div className="authorsV3Empty">Henüz yazar eklenmedi.</div>
        )}
      </section>
    </main>
  );
}

function AuthorProfilePage({ slug, content = defaultBlogContent }) {
  const authors = (Array.isArray(content.authors) ? content.authors : [])
    .filter((item)=>item?.slug && item?.name);

  const author = authors.find((item)=>item.slug===slug);

  if (!author) {
    return <main className="blog99NotFound"><img src={kaanOzkanLogo2026} alt=""/><span>YAZARLAR</span><h1>Bu yazar bulunamadı.</h1><a href="#/yazarlar">Yazarlara Dön</a></main>;
  }

  const authorPosts = (Array.isArray(content.posts) ? content.posts : [])
    .filter((post)=>post.status !== "draft" && String(post.authorSlug||"")===String(author.slug||""))
    .sort((a,b)=>Number(b.sortOrder||0)-Number(a.sortOrder||0));

  const rawAuthorBio = String(author.bio || author.shortBio || "").trim();
  const expertiseHeadingPattern = /Akademik\s+ve\s+Mesleki\s+Uzmanlık\s+Alanları\s*[:\-]?/i;
  const expertiseMatch = rawAuthorBio.match(expertiseHeadingPattern);
  const authorBiography = expertiseMatch ? rawAuthorBio.slice(0, expertiseMatch.index).trim() : rawAuthorBio;
  const expertiseSource = expertiseMatch ? rawAuthorBio.slice((expertiseMatch.index || 0) + expertiseMatch[0].length).trim() : "";
  const authorExpertise = expertiseSource
    ? expertiseSource.split(/\s*[•·▪◦]\s*|\n+/).map((item)=>item.replace(/^[-–—]\s*/, "").trim()).filter(Boolean)
    : [];

  return (
    <main className="authorV3">
      <section className="authorV3Hero">
        <div className="authorV3Hero__top">
          <a href="#/yazarlar">← YAZARLAR</a>
          <span>CONTRIBUTOR PROFILE / 2026</span>
        </div>

        <div className="authorV3Hero__layout">
          <div className="authorV3Hero__portrait">
            {author.image
              ? <img src={author.image} alt={author.name}/>
              : <span>{author.name?.charAt(0)}</span>}
            <div className="authorV3Hero__portraitFrame"/>
            <small>KAAN ÖZKAN JOURNAL</small>
          </div>

          <div className="authorV3Hero__copy">
            <span>YAZAR PROFİLİ</span>
            <h1>{author.name}</h1>
            <p className="authorV3Hero__role">{author.role}</p>

            {author.shortBio && <p className="authorV3Hero__lead">{author.shortBio}</p>}

            <div className="authorV3Hero__stats">
              <article>
                <b>{String(authorPosts.length).padStart(2,"0")}</b>
                <small>YAYINLANMIŞ<br/>İÇERİK</small>
              </article>
              <i/>
              <article>
                <b>∞</b>
                <small>FARKLI<br/>PERSPEKTİF</small>
              </article>
            </div>
          </div>
        </div>
      </section>

      <section className="authorV3Bio">
        <div className="authorV3Bio__label">
          <span>01</span>
          <small>BİYOGRAFİ</small>
        </div>
        <div className="authorV3Bio__content">
          <p>{authorBiography}</p>
          {authorExpertise.length > 0 && (
            <div className="authorV3Bio__expertise">
              <h3>Akademik ve Mesleki Uzmanlık Alanları</h3>
              <ul>
                {authorExpertise.map((item,index)=>(
                  <li key={`${author.slug}-expertise-${index}`}>{item}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </section>

      {authorPosts.length > 0 && (
        <section className="authorV3Works">
          <div className="authorV3Works__head">
            <span>02 / SELECTED WORKS</span>
            <h2>Yazarın <em>Yazıları</em></h2>
          </div>

          <div className="authorV3Works__grid">
            {authorPosts.map((post,index)=>(
              <a href={`#/blog/${post.slug}`} className="authorV3Work" key={post.id||post.slug}>
                <div>
                  <img src={post.image} alt={post.title}/>
                  <span>{String(index+1).padStart(2,"0")}</span>
                </div>
                <small>{post.category} · {post.readTime}</small>
                <h3>{post.title}</h3>
                <strong>YAZIYI OKU ↗</strong>
              </a>
            ))}
          </div>
        </section>
      )}
    </main>
  );
}

function BlogArticlePage({ slug, content = defaultBlogContent }) {
  const posts=(Array.isArray(content.posts)?content.posts:[]).filter(post=>post.status!=="draft");
  const post=posts.find(item=>item.slug===slug);

  if(!post) {
    return (
      <main className="blog99NotFound">
        <img src={kaanOzkanLogo2026} alt=""/>
        <span>BLOG</span>
        <h1>Bu yazı bulunamadı.</h1>
        <a href="#/blog">Blog'a Dön</a>
      </main>
    );
  }

  const paragraphs=Array.isArray(post.body)
    ? post.body
    : String(post.body||"").split(/\n\s*\n/).filter(Boolean);

  const authors=(Array.isArray(content.authors)?content.authors:[])
    .filter((item)=>item?.slug && item?.name);

  const postAuthorSlug=String(post.authorSlug||"").trim();
  const author=postAuthorSlug
    ? (authors.find((item)=>String(item.slug||"").trim()===postAuthorSlug)||null)
    : null;

  const articleShareUrl =
    typeof window !== "undefined"
      ? `${window.location.origin}${window.location.pathname}#/blog/${post.slug}`
      : `https://www.ailedanismanikaanozkan.com/#/blog/${post.slug}`;

  const shareArticle=async()=>{
    try{
      if(navigator.share){
        await navigator.share({
          title:post.title,
          text:post.excerpt||"",
          url:articleShareUrl,
        });
        return;
      }

      await navigator.clipboard.writeText(articleShareUrl);
      window.alert("Yazının bağlantısı kopyalandı.");
    }catch(error){
      if(error?.name==="AbortError") return;

      try{
        await navigator.clipboard.writeText(articleShareUrl);
        window.alert("Yazının bağlantısı kopyalandı.");
      }catch{
        window.prompt("Yazının bağlantısını kopyalayın:",articleShareUrl);
      }
    }
  };

  const related=posts.filter((item)=>item.slug!==post.slug).slice(0,3);

  return (
    <main className="articleCinePage">
      <div className="articleCineProgress" aria-hidden="true"/>

      <section className="articleCineHero cin3d articleV3Hero">
        <div className="articleV3Hero__edition" aria-hidden="true">EDITORIAL / 2026</div>
        <div className="articleCineHero__ambient" aria-hidden="true">
          <img src={post.image} alt="" />
          <span/>
        </div>

        <div className="articleCineHero__topbar">
          <a href="#/blog">← Blog'a Dön</a>
          <button type="button" onClick={shareArticle}>Paylaş ↗</button>
        </div>

        <div className="articleCineHero__inner">
          <div className="articleCineHero__copy">
            <span className="articleCineHero__eyebrow">{post.category}</span>

            <h1>{post.title}</h1>

            {post.excerpt && <p>{post.excerpt}</p>}

            <div className="articleCineHero__meta">
              <time>{post.date}</time>
              <i/>
              <span>{post.readTime}</span>
            </div>

            {author && (
              <a className="articleCineHero__author" href={`#/yazarlar/${author.slug}`}>
                <div>
                  {author.image
                    ? <img src={author.image} alt={author.name}/>
                    : <span>{author.name?.charAt(0)}</span>}
                </div>

                <p>
                  <small>YAZAR</small>
                  <strong>{author.name}</strong>
                  <em>{author.role}</em>
                </p>

                <b>↗</b>
              </a>
            )}
          </div>

          <div className="articleCineHero__visual">
            <div className="articleCineHero__frame">
              <img src={post.image} alt={post.title}/>
              <div className="articleCineHero__frameInfo">
                <span>{post.category}</span>
                <small>{post.date} · {post.readTime}</small>
              </div>
            </div>
          </div>
        </div>

        <div className="articleCineHero__scroll" aria-hidden="true">
          <span/>
          <small></small>
        </div>
      </section>



      <section className={`articleCineBody ${author ? "has-author" : ""}`}>
        <article className="articleCineBody__article">
          {paragraphs.map((block,index)=>{
            const item = typeof block === "string" ? { type:"paragraph", text:block } : block;

            if(item?.type==="heading"){
              return (
                <div className="articleRichHeading articleRichHeading--plain" key={index}>
                  <h2>{item.text}</h2>
                </div>
              );
            }

            if(item?.type==="riskTable"){
              return (
                <figure className="articleRichFigure articleRichFigure--risk" key={index}>
                  <div className="articleRichRiskGrid">
                    {(item.columns||[]).map((column,columnIndex)=>(
                      <section key={columnIndex}>
                        <div className="articleRichRiskGrid__head">
                          <h3>{column.title}</h3>
                        </div>
                        <ul>
                          {(column.items||[]).map((entry,entryIndex)=><li key={entryIndex}>{entry}</li>)}
                        </ul>
                      </section>
                    ))}
                  </div>
                  <figcaption>{item.caption}</figcaption>
                </figure>
              );
            }

            if(item?.type==="impactDiagram"){
              return (
                <figure className="articleRichFigure articleRichFigure--impact" key={index}>
                  <div className="articleRichImpact articleRichImpact--source">
                    <div className="articleRichImpact__node is-top"><span>ANNE</span></div>
                    <div className="articleRichImpact__node is-left"><span>BABA</span></div>
                    <div className="articleRichImpact__node is-right"><span>BEBEK</span></div>
                    <div className="articleRichImpact__node is-bottom"><span>AİLE</span></div>

                    <div className="articleRichImpact__arrows" aria-hidden="true">
                      <span className="arrowStem arrowStem--vertical"></span>
                      <span className="arrowStem arrowStem--horizontal"></span>
                      <span className="arrowHead arrowHead--up"></span>
                      <span className="arrowHead arrowHead--down"></span>
                      <span className="arrowHead arrowHead--left"></span>
                      <span className="arrowHead arrowHead--right"></span>
                    </div>
                  </div>
                  <figcaption>{item.caption}</figcaption>
                </figure>
              );
            }

            if(item?.type==="recommendation"){
              const parts=String(item.text||"").split(":");
              const recTitle=parts.length>1?parts.shift():"";
              const recBody=parts.join(":").trim();
              return (
                <section className="articlePlainRecommendation" key={index}>
                  {recTitle && <h3>{recTitle}</h3>}
                  <p>{recBody || item.text}</p>
                </section>
              );
            }

            if(item?.type==="references"){
              return (
                <div className="articleRichReferences" key={index}>
                  {(item.items||[]).map((reference,referenceIndex)=>(
                    <div className="articleRichReferences__plain articleRichReferences__numbered" key={referenceIndex}>
                      <span>{referenceIndex + 1}.</span>
                      <p>{String(reference||"").replace(/^\s*\d+\s*[-.)]\s*/, "")}</p>
                    </div>
                  ))}
                </div>
              );
            }

            return (
              <div className="articleCineParagraph articleCineParagraph--plain" key={index}>
                <p>{item?.text || ""}</p>
              </div>
            );
          })}

          {post.quote && (
            <blockquote className="articleCineQuote">
              <span>“</span>
              <p>{post.quote}</p>
            </blockquote>
          )}

          <div className="articleCineNote">
            <span>BİLGİLENDİRME</span>
            <p>
              Bu içerik genel bilgilendirme amacıyla hazırlanmıştır. Kişisel
              ihtiyaçların değerlendirilmesi için profesyonel görüşme gerekebilir.
            </p>
          </div>
        </article>

        <aside className="articleCineRail">
          <div className="articleCineRail__card">
            <span>YAZI BİLGİLERİ</span>

            <div className="articleCineRail__row">
              <small>KATEGORİ</small>
              <strong>{post.category}</strong>
            </div>

            <div className="articleCineRail__row">
              <small>OKUMA</small>
              <strong>{post.readTime}</strong>
            </div>

            <button type="button" onClick={shareArticle}>
              Yazıyı Paylaş
              <b>↗</b>
            </button>
          </div>

          {author && (
            <a className="articleCineRail__author" href={`#/yazarlar/${author.slug}`}>
              <div className="articleCineRail__avatar">
                {author.image
                  ? <img src={author.image} alt={author.name}/>
                  : <span>{author.name?.charAt(0)}</span>}
              </div>

              <small>YAZAR</small>
              <h3>{author.name}</h3>
              <p>{author.role}</p>
              <span>Yazar profilini görüntüle ↗</span>
            </a>
          )}
        </aside>
      </section>

      <section className="articleCineEnd">
        <div>
          <span>YAZININ SONU</span>
          <h2>
            Okuduğunuz için
            <strong>teşekkür ederiz.</strong>
          </h2>
          <p>
            İçeriği faydalı bulduysanız bağlantıyı paylaşarak daha fazla kişiye
            ulaşmasına katkı sağlayabilirsiniz.
          </p>
        </div>

        <button type="button" onClick={shareArticle}>
          Yazıyı Paylaş
          <span>↗</span>
        </button>
      </section>

      {related.length>0 && (
        <section className="articleCineRelated">
          <div className="articleCineRelated__head">
            <span>OKUMAYA DEVAM EDİN</span>
            <h2>Diğer yazılar</h2>
          </div>

          <div className="articleCineRelated__grid">
            {related.map((item,index)=>(
              <a
                className="articleCineRelated__card"
                href={`#/blog/${item.slug}`}
                key={item.slug}
              >
                <div>
                  <img src={item.image} alt={item.title}/>
                  <span>0{index+1}</span>
                </div>

                <small>{item.category}</small>
                <h3>{item.title}</h3>
                <p>{item.excerpt}</p>
                <b>Yazıyı Oku ↗</b>
              </a>
            ))}
          </div>
        </section>
      )}
    </main>
  );
}

